package viewer

import (
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/testutil"
	viewerpkg "github.com/anthnel/devdesk/internal/viewer"
)

// A .json opens as json, which is what the request asked for.
func TestAStructuredDocumentOpensOnItsTree(t *testing.T) {
	m := jsonModel(t)

	if m.display != displayTree {
		t.Error("a JSON document did not open on its tree")
	}
	if got := m.formatLabel(); got != "json · tree" {
		t.Errorf("formatLabel = %q, want \"json · tree\"", got)
	}
}

func TestAnXMLDocumentOpensOnItsTree(t *testing.T) {
	m := open(t, fakeSource{name: "pod.xml", content: `<pod name="web"><image>nginx</image></pod>`})

	if m.display != displayTree {
		t.Error("an XML document did not open on its tree")
	}
	if m.doc.Kind != viewerpkg.KindXML {
		t.Errorf("Kind = %q, want xml", m.doc.Kind)
	}
}

func TestATextDocumentHasNoTree(t *testing.T) {
	// A .txt, not a .md: Markdown derives a rendered display now, so it is no
	// longer an example of a document with nothing behind `f`.
	m := open(t, fakeSource{name: "notes.txt", content: "hello"})

	path := filepath.Join(t.TempDir(), "config.json")
	if err := os.WriteFile(path, []byte(`{"name":"web","port":8080}`), 0o600); err != nil {
		t.Fatal(err)
	}

	a := newWithSize(testConfig(), 120, 40)
	a.createView(command.ViewWorkspaces)
	a.currentView = command.ViewWorkspaces

	_, cmd := a.Update(uiviewer.OpenRequestMsg{Source: viewer.NewFileSource(path)})
	if cmd == nil {
		t.Fatal("opening the viewer issued no command, so the file is never read")
	}
	for _, msg := range testutil.Msgs(cmd) {
		updated, _ := a.views[command.ViewViewer].Update(msg)
		a.setView(command.ViewViewer, updated)
	}

	rendered := a.views[command.ViewViewer].Render()
	for _, want := range []string{"name", "web", "port", "8080"} {
		if !strings.Contains(rendered, want) {
			t.Errorf("the tree does not show %q:\n%s", want, rendered)
		}
	}

	title := a.views[command.ViewViewer].(uiviewer.Model).GetTitle()
	if !strings.Contains(title, "config.json") {
		t.Errorf("GetTitle() = %q, want it to name the document", title)
	}
}

